(7236010, 1119437, 156466, '<td valign="top">The darkeness of the surfer seems over manipulated given the other lighting conditions.  Not believable.</td>', 'The darkeness of the surfer seems over manipulated given the other lighting conditions.  Not believable.', '2014-07-03 11:06:41.000000', NULL, 1),
(7236012, 1119485, 156466, '<td valign="top">Not very silhouetted, is it?  Unless you''re talking the trees in the far distance.</td>', 'Not very silhouetted, is it?  Unless you''re talking the trees in the far distance.', '2014-07-03 11:08:19.000000', NULL, 1),
(7236013, 1119736, 156466, '<td valign="top">Could have been cool with more DOF.</td>', 'Could have been cool with more DOF.', '2014-07-03 11:08:48.000000', NULL, 1),
